def build_lps(pattern):
    lps = [0] * len(pattern)
    j = 0  # độ dài tiền tố = hậu tố dài nhất

    for i in range(1, len(pattern)):
        while j > 0 and pattern[i] != pattern[j]:
            j = lps[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        lps[i] = j
    return lps


def count_occurrences(s, n):
    if len(n) > len(s):
        return 0

    lps = build_lps(n)
    i = j = 0
    count = 0

    while i < len(s):
        if s[i] == n[j]:
            i += 1
            j += 1
        else:
            if j > 0:
                j = lps[j - 1]
            else:
                i += 1

        if j == len(n):
            count += 1
            j = lps[j - 1]  # cho phép chồng lấn

    return count


